package nl.smartstreamlabs.sbwdroneconfig;
import com.mojang.blaze3d.vertex.*;import net.minecraft.client.*;import net.minecraft.client.renderer.*;import net.minecraft.core.Direction;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.phys.Vec3;import org.joml.Vector3f;import software.bernie.geckolib.cache.object.*;import java.util.*;import java.io.*;
/** One resident mesh batch per installation model; only its pose palette changes. */
public final class DefenseModel{
 private static final DefenseModel[]CACHE=new DefenseModel[2];private final GeoCube[]cubes;private final BakedGeoModel model;private final ResourceLocation texture;public static DefenseModel get(int kind){if(CACHE[kind]==null)CACHE[kind]=new DefenseModel(kind);return CACHE[kind];}public static void clear(){for(int i=0;i<2;i++)if(CACHE[i]!=null){Adv01Gpu.release(CACHE[i].model);CACHE[i]=null;}}
 private DefenseModel(int kind){var geo=DefenseGeometry.MODELS[kind];texture=ResourceLocation.tryParse("sbwdroneconfig:defense/"+geo.key+".png");cubes=new GeoCube[geo.bones.size()];var bones=new ArrayList<GeoBone>();try(var in=new DataInputStream(Minecraft.getInstance().getResourceManager().getResourceOrThrow(ResourceLocation.tryParse("sbwdroneconfig:defense/"+geo.key+".bin")).open())){if(in.readInt()!=0x44454631||in.readInt()!=cubes.length)throw new IOException("Defense mesh header");for(int n=0;n<cubes.length;n++){int count=in.readInt();if(count<0||count>50000)throw new IOException("Defense mesh length");var quads=new GeoQuad[count];for(int f=0;f<count;f++){var normal=new Vector3f(in.readFloat(),in.readFloat(),in.readFloat());var vertices=new GeoVertex[4];for(int k=0;k<4;k++)vertices[k]=new GeoVertex(in.readFloat(),in.readFloat(),in.readFloat()).withUVs(in.readFloat(),in.readFloat());quads[f]=new GeoQuad(vertices,normal,Direction.getNearest(normal.x,normal.y,normal.z));}if(count>0){cubes[n]=new GeoCube(quads,Vec3.ZERO,Vec3.ZERO,new Vec3(1,1,1),0,false);MeshRenderData.register(cubes[n]);var bone=new GeoBone(null,geo.bones.get(n).name(),false,0d,false,false);bone.getCubes().add(cubes[n]);bones.add(bone);}}if(in.read()!=-1)throw new IOException("Defense trailing bytes");}catch(IOException e){throw new IllegalStateException("Cannot load "+geo.key,e);}model=new BakedGeoModel(bones,null);}
 public void draw(int kind,PoseStack p,MultiBufferSource buffers,int light,int overlay,float service,double scan,float[]covers,boolean preview,boolean valid){var poses=DefenseGeometry.MODELS[kind].transforms(service,scan,covers);var type=preview?RenderType.entityTranslucent(texture):RenderType.entityCutoutNoCull(texture);var batch=buffers instanceof MultiBufferSource.BufferSource?Adv01Gpu.batch(model):null;float r=preview?(valid?.45f:1):1,g=preview?(valid?1:.2f):1,b=preview?(valid?.65f:.2f):1,a=preview?.35f:1;if(batch!=null)batch.begin();for(int i=0;i<cubes.length;i++)if(cubes[i]!=null){p.pushPose();p.last().pose().mul(new org.joml.Matrix4f(poses[i]));p.last().normal().mul(new org.joml.Matrix3f(new org.joml.Matrix4f(poses[i])));if(batch!=null)batch.pose(cubes[i],p);else emit(p,buffers.getBuffer(type),MeshRenderData.get(cubes[i]),light,overlay,r,g,b,a);p.popPose();}if(batch!=null)batch.draw(type,light,overlay,r,g,b,a);}
 private static void emit(PoseStack poses,VertexConsumer consumer,MeshRenderData data,int light,int overlay,float red,float green,float blue,float alpha){var m=poses.last().pose();var n=poses.last().normal();var v=data.values;if(MeshBulkWriter.draw(consumer,data,m,n,light,overlay,red,green,blue,alpha))return;for(int at=0;at<v.length;at+=23){float a=v[at],b=v[at+1],c=v[at+2];float nx=n.m00()*a+n.m10()*b+n.m20()*c,ny=n.m01()*a+n.m11()*b+n.m21()*c,nz=n.m02()*a+n.m12()*b+n.m22()*c;for(int i=at+3;i<at+23;i+=5){float x=v[i],y=v[i+1],z=v[i+2];float px=m.m00()*x+m.m10()*y+m.m20()*z+m.m30(),py=m.m01()*x+m.m11()*y+m.m21()*z+m.m31(),pz=m.m02()*x+m.m12()*y+m.m22()*z+m.m32();consumer.vertex(px,py,pz,red,green,blue,alpha,v[i+3],v[i+4],overlay,light,nx,ny,nz);}}}
}
